package br.com.tapeteskalke.service; import br.com.tapeteskalke.repository.*; import java.math.BigDecimal; import java.time.*; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class DashboardService { private final VendaRepository vendas; private final ClienteRepository clientes; private final ProdutoRepository produtos; private final Clock clock; public DashboardService(VendaRepository vendas,ClienteRepository clientes,ProdutoRepository produtos,Clock clock){this.vendas=vendas;this.clientes=clientes;this.produtos=produtos;this.clock=clock;} @Transactional(readOnly=true) public Map<String,Object> summary(){var today=LocalDate.now(clock);var first=today.withDayOfMonth(1);var low=produtos.lowStock();var clients=clientes.countByDeletedAtIsNull();Map<String,Object> m=new LinkedHashMap<>();m.put("vendasHoje",vendas.totalFinalized(today,today));m.put("vendasMes",vendas.totalFinalized(first,today));m.put("totalClientes",clients);m.put("itensEstoque",low.size());m.put("estoqueBaixo",low.stream().map(p->Map.of("id",p.getId(),"nome",p.getNome(),"comercial",p.getEstoqueComercial(),"producao",p.getEstoqueProducao())).toList());return m;} }